css:
.distinctsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2440;
    background: linear-gradient(160deg, #f4f1ea 0%, #eef0f6 100%);
    border-radius: 18px;
}

.distinctsim-container * {
    box-sizing: border-box;
}

.distinctsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #16213e 0%, #283562 55%, #3a4a85 100%);
    color: #f6f3ea;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(22, 33, 62, 0.32);
    border-bottom: 4px solid #c9a227;
}

.distinctsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.distinctsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f0d680;
    background: rgba(201, 162, 39, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.distinctsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e7e3d6;
}

.distinctsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #283562;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.distinctsim-period-counter #currentDay,
.distinctsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #16213e;
}

.distinctsim-round-name {
    background: #e3e7f4;
    color: #283562;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.distinctsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3412;
    background: #fbe8df;
    padding: 4px 12px;
    border-radius: 999px;
}

.distinctsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.distinctsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0ddd0;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.07);
    border-top: 4px solid #3a4a85;
}

.distinctsim-card-diff { border-top-color: #c9a227; }
.distinctsim-card-fit { border-top-color: #2f6fb0; }
.distinctsim-card-margin { border-top-color: #1f8a5b; }
.distinctsim-card-resil { border-top-color: #6a4fb0; }

.distinctsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b6f82;
}

.distinctsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #16213e;
}

.distinctsim-card-diff .distinctsim-value { color: #a8851a; }
.distinctsim-card-fit .distinctsim-value { color: #2f6fb0; }
.distinctsim-card-margin .distinctsim-value { color: #1f8a5b; }
.distinctsim-card-resil .distinctsim-value { color: #6a4fb0; }

.distinctsim-sublabel {
    font-size: 0.75rem;
    color: #7a7e90;
    line-height: 1.35;
}

.distinctsim-diff-distinctive .distinctsim-value { color: #1f8a5b; }
.distinctsim-diff-stuck .distinctsim-value { color: #9a3412; }

.distinctsim-margin-loss .distinctsim-value { color: #c0392b; }
.distinctsim-margin-loss { border-top-color: #c0392b; }

.distinctsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #16213e;
    color: #f1eede;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 4px solid #c9a227;
}

.distinctsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0d680;
}

.distinctsim-budget-over #budgetDisplay {
    color: #ff9b8a;
}

.distinctsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c9a227;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.06);
}

.distinctsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.distinctsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #16213e;
    margin-bottom: 6px;
}

.distinctsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #353c54;
}

.distinctsim-briefing-text strong { color: #1f8a5b; }
.distinctsim-briefing-text em { color: #9a3412; font-style: italic; }

.distinctsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0ddd0;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.07);
}

.distinctsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #16213e;
    border-bottom: 2px solid #eceadf;
    padding-bottom: 8px;
}

.distinctsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #283562;
    margin: 14px 0 6px;
}

.distinctsim-container select,
.distinctsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c8c4b4;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbfaf5;
    color: #1c2440;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.distinctsim-container select:focus,
.distinctsim-container input[type="number"]:focus {
    outline: none;
    border-color: #c9a227;
    box-shadow: 0 0 0 3px rgba(201, 162, 39, 0.18);
}

.distinctsim-container select option {
    background-color: #ffffff;
    color: #1c2440;
}

.distinctsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c9a227;
}

.distinctsim-range-readout,
.distinctsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #283562;
    margin-top: 4px;
}

.distinctsim-range-readout span:last-child,
.distinctsim-alloc-readout span:nth-child(2) {
    color: #a8851a;
    font-weight: 800;
}

.distinctsim-hint {
    font-size: 0.8rem;
    color: #7a7e90;
    margin-top: 4px;
    line-height: 1.4;
}

.distinctsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.distinctsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f4ec;
    border: 1px solid #e6e2d4;
    border-radius: 9px;
    padding: 8px 12px;
}

.distinctsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #283562;
}

.distinctsim-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.distinctsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.distinctsim-container .btn-primary {
    background: linear-gradient(135deg, #283562 0%, #3a4a85 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 16px rgba(40, 53, 98, 0.30);
}

.distinctsim-container .btn-primary:hover {
    filter: brightness(1.10);
}

.distinctsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c8c4b4;
    color: #6b6f82;
}

.distinctsim-coach {
    background: #16213e;
    color: #eceadf;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(22, 33, 62, 0.24);
    border-left: 4px solid #c9a227;
}

.distinctsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0d680;
    margin-bottom: 8px;
}

.distinctsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.distinctsim-coach-body strong { color: #f0d680; }
.distinctsim-coach-body em { color: #ffb59c; font-style: italic; }

.distinctsim-history,
.distinctsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0ddd0;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.07);
}

.distinctsim-history h3,
.distinctsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #16213e;
}

.distinctsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #283562;
}

.distinctsim-container table#usfHistoryTable th {
    background: #eceadf;
    color: #16213e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd8c6;
}

.distinctsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0eee4;
}

.distinctsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf9f3;
}

.distinctsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .distinctsim-container {
        padding: 14px;
    }
    .distinctsim-header h1 {
        font-size: 1.7rem;
    }
    .distinctsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .distinctsim-value {
        font-size: 2rem;
    }
    .distinctsim-clock {
        margin-left: 0;
    }
    .distinctsim-period-counter {
        font-size: 0.88rem;
    }
    .distinctsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .distinctsim-alloc-row {
        flex-wrap: wrap;
    }
    .distinctsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .distinctsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light modal, distinctsim) ---- */
.distinctsim-completion { padding: 8px 4px 4px; }
.distinctsim-cm-head { text-align: center; margin-bottom: 16px; }
.distinctsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f6f6a; }
.distinctsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #6a9b96; }
.distinctsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #14213d; }
.distinctsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.distinctsim-cm-yes { background: rgba(47,111,106,0.14); color: #256b64; border: 1px solid rgba(47,111,106,0.5); }
.distinctsim-cm-no { background: rgba(199,154,60,0.16); color: #8a6a1f; border: 1px solid rgba(199,154,60,0.5); }
.distinctsim-cm-fail { background: rgba(192,57,43,0.12); color: #b0392b; border: 1px solid rgba(192,57,43,0.45); }
.distinctsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.distinctsim-cm-metric { flex: 1 1 110px; min-width: 100px; background: rgba(20,33,61,0.06); border: 1px solid rgba(20,33,61,0.16); border-radius: 10px; padding: 10px 8px; text-align: center; }
.distinctsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #23304f; }
.distinctsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a6577; text-transform: uppercase; letter-spacing: 0.03em; }
.distinctsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #14213d; }
.distinctsim-cm-insights { margin: 0; padding-left: 20px; }
.distinctsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2b3547; }

