(function() {
    'use strict';

    class DistinctiveOfferAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Designing the Distinctive Offer`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_DIFF = 42;            // Differentiation Index now
            this.DISTINCTIVE_DIFF = 70;      // distinctive threshold
            this.START_FIT = 30;             // segment-fit, low headroom start
            this.START_MARGIN = 5.0;         // ≈ €5.0M operating surplus (8% of €62M)
            this.START_RESIL = 25;           // competitive resilience, low start
            this.BUDGET_CAP = 6.0;           // €6.0M strategic-investment budget
            this.RETAIN_RESERVE = 2.0;       // separate faculty-retention reserve cap

            // Concept truths.
            this.TRUE_VRIN = `sustainability`;
            this.TRUE_WEAK = `depth`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    diff: this.START_DIFF,
                    fit: this.START_FIT,
                    margin: this.START_MARGIN,
                    resil: this.START_RESIL,
                    budgetUsed: 0,
                    retainUsed: 0,
                    profLost: false,
                    spendingWar: false,
                    diffHistory: [this.START_DIFF],
                    fitHistory: [this.START_FIT],
                    resilHistory: [this.START_RESIL],
                    marginHistory: [this.START_MARGIN],
                    lastCoach: ``
                };
            }
            // Seeded defaults are deliberately MIDDLING — not the textbook-correct play.
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    vrin: `breadth`,
                    concorde: `money`,
                    honesty: 55,
                    focus: `four`,
                    stop: 4,
                    flagship: 3.0,
                    brand: 1.5,
                    discount: 0.0,
                    metoo: 1.5,
                    position: `generalist`,
                    differentiators: `mixed`,
                    retain: `partial`,
                    retainSpend: 0.6,
                    viability: `volume`,
                    roadmap: `waitsee`,
                    board: `hope`,
                    conviction: 65
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const vrin = document.getElementById(`vrinInput`);
                const conc = document.getElementById(`concordeInput`);
                const hon = document.getElementById(`honestyInput`);
                if (vrin) decisions.vrin = vrin.value;
                if (conc) decisions.concorde = conc.value;
                if (hon) decisions.honesty = parseInt(hon.value, 10);
                if (!Number.isFinite(decisions.honesty) || decisions.honesty < 0 || decisions.honesty > 100) {
                    warn(`warn_honesty_range`); return false;
                }
            } else if (round === 2) {
                const fo = document.getElementById(`focusInput`);
                const st = document.getElementById(`stopInput`);
                if (fo) decisions.focus = fo.value;
                if (st) decisions.stop = parseInt(st.value, 10);
                if (!Number.isFinite(decisions.stop) || decisions.stop < 0 || decisions.stop > 9) {
                    warn(`warn_stop_range`); return false;
                }
                const fl = document.getElementById(`flagshipInput`);
                const br = document.getElementById(`brandInput`);
                const di = document.getElementById(`discountInput`);
                const mt = document.getElementById(`metooInput`);
                if (fl) decisions.flagship = parseFloat(fl.value);
                if (br) decisions.brand = parseFloat(br.value);
                if (di) decisions.discount = parseFloat(di.value);
                if (mt) decisions.metoo = parseFloat(mt.value);
                const parts = [decisions.flagship, decisions.brand, decisions.discount, decisions.metoo];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.flagship + decisions.brand + decisions.discount + decisions.metoo) * 10) / 10;
                if (Math.abs(total - this.BUDGET_CAP) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const po = document.getElementById(`positionInput`);
                const df = document.getElementById(`differentiatorsInput`);
                const re = document.getElementById(`retainInput`);
                const rs = document.getElementById(`retainSpendInput`);
                if (po) decisions.position = po.value;
                if (df) decisions.differentiators = df.value;
                if (re) decisions.retain = re.value;
                if (rs) decisions.retainSpend = parseFloat(rs.value);
                if (!Number.isFinite(decisions.retainSpend) || decisions.retainSpend < 0 || decisions.retainSpend > this.RETAIN_RESERVE) {
                    warn(`warn_retain_range`); return false;
                }
            } else if (round === 4) {
                const vi = document.getElementById(`viabilityInput`);
                const ro = document.getElementById(`roadmapInput`);
                const bo = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (vi) decisions.viability = vi.value;
                if (ro) decisions.roadmap = ro.value;
                if (bo) decisions.board = bo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let diffDelta = 0, fitDelta = 0, resilDelta = 0, marginDelta = 0;
            let spend = 0, retainSpend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // VRIN diagnosis: only the sustainability specialism is valuable, rare, inimitable.
                if (d.vrin === this.TRUE_VRIN) {
                    diffDelta += 4; resilDelta += 10; fitDelta += 4; coachKey = `coach_r1_vrin_right`;
                } else if (d.vrin === `rankings`) {
                    diffDelta -= 2; resilDelta -= 4; coachKey = `coach_r1_rankings`;
                } else if (d.vrin === `price`) {
                    diffDelta -= 4; resilDelta -= 6; marginDelta -= 0.3; coachKey = `coach_r1_price`;
                } else {
                    diffDelta -= 5; resilDelta -= 6; coachKey = `coach_r1_breadth`;
                }

                // Reading Concorde's true weakness: it bought credibility, it did not build the capability.
                if (d.concorde === this.TRUE_WEAK) {
                    resilDelta += 8; diffDelta += 1;
                    if (d.vrin === this.TRUE_VRIN) coachKey = `coach_r1_diag_sharp`;
                } else if (d.concorde === `brand`) {
                    resilDelta -= 4; coachKey = `coach_r1_brand`;
                } else if (d.concorde === `ai`) {
                    resilDelta -= 6; diffDelta -= 3; coachKey = `coach_r1_ai`;
                } else {
                    resilDelta -= 6; coachKey = `coach_r1_money`;
                }

                // Candour about being stuck-in-the-middle and willing to trade off.
                if (d.honesty >= 60) { fitDelta += 6; resilDelta += 3; }
                else if (d.honesty <= 25) { fitDelta -= 6; resilDelta -= 3; coachKey = `coach_r1_lowhonesty`; }

                summaryKey = (d.vrin === this.TRUE_VRIN && d.concorde === this.TRUE_WEAK) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Concentrate the €6M vs peanut-butter vs spending war vs ungrounded copy.
                switch (d.focus) {
                    case `concentrate`: diffDelta += 8; fitDelta += 12; resilDelta += 7; coachKey = `coach_r2_concentrate`; break;
                    case `four`: diffDelta += 3; fitDelta += 5; resilDelta += 3; coachKey = `coach_r2_four`; break;
                    case `spread`: diffDelta -= 6; fitDelta -= 4; resilDelta -= 4; coachKey = `coach_r2_spread`; break;
                    case `rivalcopy`: diffDelta += 2; fitDelta -= 6; resilDelta -= 8; coachKey = `coach_r2_rivalcopy`; break;
                }

                // The power of "no": stopping 3–4 programs frees resources and sharpens focus.
                // Stopping nothing = stuck-in-the-middle; cutting everything = self-destruction.
                if (d.stop >= 3 && d.stop <= 5) { diffDelta += 5; fitDelta += 6; marginDelta += 0.6; }
                else if (d.stop >= 1 && d.stop <= 2) { diffDelta += 2; marginDelta += 0.2; }
                else if (d.stop === 0) { diffDelta -= 8; fitDelta -= 5; marginDelta -= 0.3; coachKey = `coach_r2_nostop`; }
                else { diffDelta -= 6; fitDelta -= 8; resilDelta -= 6; marginDelta -= 0.6; coachKey = `coach_r2_overcut`; }

                // Where the €6M actually lands. The discount lever is a spending/price war (Common Error 1):
                // it never improves differentiation and it erodes margin €-for-€.
                spend = d.flagship + d.brand + d.discount + d.metoo;
                diffDelta += d.flagship * 1.8;        // flagship capability build → differentiation
                resilDelta += d.flagship * 1.6;
                fitDelta += d.brand * 3.0;            // targeted brand/admissions → segment-fit
                diffDelta += d.brand * 0.6;
                if (d.discount > 0) {
                    marginDelta -= d.discount * 0.9;  // discount erodes margin, buys no distinctiveness
                    resilDelta -= d.discount * 2.0;
                    fitDelta -= d.discount * 1.0;
                    if (d.discount >= 1.5) { ds.spendingWar = true; coachKey = `coach_r2_war`; }
                }
                fitDelta -= d.metoo * 1.2;            // funding me-too programs dilutes the position
                diffDelta -= d.metoo * 1.4;

                summaryKey = (d.focus === `concentrate` && d.stop >= 3 && d.stop <= 5 && d.discount === 0) ? `sum_r2_good`
                    : (d.discount >= 1.5 || d.focus === `spread` ? `sum_r2_war` : `sum_r2_weak`);
            } else if (round === 3) {
                // Anchor the position in owned capability (Common Error 4) and build inimitable differentiators.
                switch (d.position) {
                    case `owned`: diffDelta += 8; resilDelta += 12; fitDelta += 6; coachKey = `coach_r3_owned`; break;
                    case `match`: diffDelta -= 8; resilDelta -= 8; marginDelta -= 0.8; coachKey = `coach_r3_match`; break;
                    case `quantum`: diffDelta += 3; resilDelta -= 12; fitDelta -= 4; coachKey = `coach_r3_quantum`; break;
                    case `generalist`: diffDelta -= 6; resilDelta -= 4; coachKey = `coach_r3_generalist`; break;
                }

                switch (d.differentiators) {
                    case `defensible`: diffDelta += 6; resilDelta += 8; fitDelta += 5;
                        if (d.position === `owned`) coachKey = `coach_r3_defensible`; break;
                    case `mixed`: diffDelta -= 5; marginDelta -= 0.4; coachKey = `coach_r3_mixed`; break;
                    case `aimodule`: diffDelta -= 3; resilDelta -= 4; coachKey = `coach_r3_aimodule`; break;
                }

                // Retain the lead professor — capabilities live in people (Common Error 3 / poaching).
                retainSpend = d.retainSpend;
                if (d.retain === `retain` && d.retainSpend >= 0.5) {
                    resilDelta += 12; diffDelta += 3;
                    if (d.position === `owned`) coachKey = `coach_r3_retain`;
                } else if (d.retain === `partial` || (d.retain === `retain` && d.retainSpend < 0.5)) {
                    resilDelta -= 6; diffDelta -= 3; coachKey = `coach_r3_partial`;
                } else {
                    ds.profLost = true;
                    resilDelta -= 16; diffDelta -= 10; coachKey = `coach_r3_letgo`;
                }

                summaryKey = (d.position === `owned` && d.differentiators === `defensible` && d.retain === `retain` && d.retainSpend >= 0.5) ? `sum_r3_good`
                    : (d.position === `match` || d.retain === `letgo` ? `sum_r3_war` : `sum_r3_weak`);
            } else if (round === 4) {
                // Reconcile distinctiveness with viability (Common Error 5).
                switch (d.viability) {
                    case `premium`: marginDelta += 1.6; resilDelta += 6; diffDelta += 2; coachKey = `coach_r4_premium`; break;
                    case `volume`: marginDelta -= 1.2; fitDelta -= 4; resilDelta -= 4; diffDelta -= 3; coachKey = `coach_r4_volume`; break;
                    case `subsidy`: marginDelta -= 1.8; resilDelta -= 6; coachKey = `coach_r4_subsidy`; break;
                }

                switch (d.roadmap) {
                    case `sequenced`: resilDelta += 12; fitDelta += 6; diffDelta += 2; coachKey = (d.viability === `premium`) ? `coach_r4_sequenced` : coachKey; break;
                    case `cutfast`: resilDelta -= 8; marginDelta += 0.3; coachKey = `coach_r4_cutfast`; break;
                    case `waitsee`: resilDelta -= 10; diffDelta -= 4; coachKey = `coach_r4_waitsee`; break;
                }

                switch (d.board) {
                    case `evidence`: resilDelta += 10; diffDelta += 2; fitDelta += 4;
                        if (d.viability === `premium` && d.roadmap === `sequenced`) coachKey = `coach_r4_evidence`; break;
                    case `spend`: marginDelta -= 1.0; resilDelta -= 8; diffDelta -= 2; ds.spendingWar = true; coachKey = `coach_r4_spend`; break;
                    case `hope`: resilDelta -= 6; marginDelta -= 0.4; coachKey = `coach_r4_hope`; break;
                }

                resilDelta += (d.conviction - 60) / 10;
            }

            // Resource accounting (separate pools).
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 10) / 10;
            ds.retainUsed = Math.round((ds.retainUsed + retainSpend) * 10) / 10;

            // Apply deltas with bounds. Meters start low and keep headroom so late wrong levers register.
            ds.diff = Math.max(0, Math.min(100, ds.diff + diffDelta));
            ds.fit = Math.max(0, Math.min(100, ds.fit + fitDelta));
            ds.resil = Math.max(0, Math.min(100, ds.resil + resilDelta));
            ds.margin = Math.round((ds.margin + marginDelta) * 10) / 10;

            ds.diffHistory.push(Math.round(ds.diff));
            ds.fitHistory.push(Math.round(ds.fit));
            ds.resilHistory.push(Math.round(ds.resil));
            ds.marginHistory.push(Math.round(ds.margin * 10) / 10);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                diff: Math.round(ds.diff),
                diffDelta: Math.round(diffDelta),
                fit: Math.round(ds.fit),
                fitDelta: Math.round(fitDelta),
                margin: Math.round(ds.margin * 10) / 10,
                marginDelta: Math.round(marginDelta * 10) / 10,
                resil: Math.round(ds.resil),
                resilDelta: Math.round(resilDelta),
                budgetUsed: ds.budgetUsed,
                spendingWar: ds.spendingWar,
                profLost: ds.profLost,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // Locale-aware EUR. EN: €2.4M (symbol before). ES: 2,4 M€ (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const n = Math.round(Number(v) * 10) / 10;
            if (lang === `es`) {
                const s = n.toFixed(1).replace(`.`, `,`);
                return s + ` M€`;
            }
            return `€` + n.toFixed(1) + `M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`diffDisplay`, `domainState.diff`, (v) => {
                const card = document.querySelector(`.distinctsim-card-diff`);
                if (card) {
                    card.classList.toggle(`distinctsim-diff-distinctive`, Number(v) >= this.DISTINCTIVE_DIFF);
                    card.classList.toggle(`distinctsim-diff-stuck`, Number(v) < 55);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`fitDisplay`, `domainState.fit`, (v) => Math.round(Number(v)));
            uiManager.bind(`resilDisplay`, `domainState.resil`, (v) => Math.round(Number(v)));
            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const card = document.querySelector(`.distinctsim-card-margin`);
                if (card) card.classList.toggle(`distinctsim-margin-loss`, Number(v) < 0);
                return this._fmtMoney(v);
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.distinctsim-budget-bar`);
                if (card) card.classList.toggle(`distinctsim-budget-over`, Number(v) > this.BUDGET_CAP + 0.001);
                const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
                const used = Math.round(Number(v) * 10) / 10;
                if (lang === `es`) {
                    return used.toFixed(1).replace(`.`, `,`) + ` M€ / 6,0 M€`;
                }
                return `€` + used.toFixed(1) + `M / €6.0M`;
            });

            const self = this;

            // Honesty slider readout.
            const hon = document.getElementById(`honestyInput`);
            const honReadout = document.getElementById(`honestyReadout`);
            if (hon && honReadout) {
                honReadout.textContent = hon.value;
                hon.addEventListener(`input`, function() { honReadout.textContent = hon.value; });
            }

            // €6M allocation live total.
            const allocIds = [`flagshipInput`, `brandInput`, `discountInput`, `metooInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = self._fmtMoney(total);
                const bar = document.querySelector(`.distinctsim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.BUDGET_CAP) > 0.001) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

