        getChartData(state) {
            const ds = state.domainState;
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const labels = ds.diffHistory.map((_, i) => (i === 0 ? t(`chart_start`) : `R` + i));
            return {
                distinctChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.diffHistory },
                        { data: ds.fitHistory },
                        { data: ds.resilHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const diff = Math.round(ds.diff);
            const fit = Math.round(ds.fit);
            const resil = Math.round(ds.resil);
            const margin = Math.round(ds.margin * 10) / 10;
            const composite = Math.round(Math.min(100, diff) * 0.32 + fit * 0.22 + resil * 0.26 + Math.max(0, Math.min(100, (margin / 8) * 100)) * 0.20);
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const metBadge = s.sound
                ? `<span class="distinctsim-cm-badge distinctsim-cm-yes">` + T(`cm_sound`) + `</span>`
                : `<span class="distinctsim-cm-badge distinctsim-cm-no">` + T(`cm_notsound`) + `</span>`;
            let failBadges = ``;
            if (s.spendingWar) failBadges += ` <span class="distinctsim-cm-badge distinctsim-cm-fail">` + T(`cm_war`) + `</span>`;
            if (s.profLost) failBadges += ` <span class="distinctsim-cm-badge distinctsim-cm-fail">` + T(`cm_profgone`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const marginTxt = (typeof s.margin === `number`) ? s.margin.toFixed(1) : `0.0`;
            const metrics = ``
                + `<div class="distinctsim-cm-metric"><span class="distinctsim-cm-mv">` + Math.round(s.diff || 0) + `</span><span class="distinctsim-cm-ml">` + T(`cm_m_diff`) + `</span></div>`
                + `<div class="distinctsim-cm-metric"><span class="distinctsim-cm-mv">` + Math.round(s.fit || 0) + `</span><span class="distinctsim-cm-ml">` + T(`cm_m_fit`) + `</span></div>`
                + `<div class="distinctsim-cm-metric"><span class="distinctsim-cm-mv">` + Math.round(s.resil || 0) + `</span><span class="distinctsim-cm-ml">` + T(`cm_m_resil`) + `</span></div>`
                + `<div class="distinctsim-cm-metric"><span class="distinctsim-cm-mv">` + marginTxt + `</span><span class="distinctsim-cm-ml">` + T(`cm_m_margin`) + `</span></div>`;
            return ``
                + `<div class="distinctsim-completion">`
                +   `<div class="distinctsim-cm-head">`
                +     `<div class="distinctsim-cm-score">` + score + `<span class="distinctsim-cm-score-max">/100</span></div>`
                +     `<div class="distinctsim-cm-grade">` + grade + ` ` + metBadge + failBadges + `</div>`
                +   `</div>`
                +   `<div class="distinctsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="distinctsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="distinctsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const diff = Math.round(ds.diff);
            const fit = Math.round(ds.fit);
            const resil = Math.round(ds.resil);
            const margin = Math.round(ds.margin * 10) / 10;

            const distinctive = diff >= this.DISTINCTIVE_DIFF;
            const viable = margin > 0;
            const defensible = resil >= 60;
            const composite = this._composite(ds);

            let performanceKey = `grade_stuck`;
            if (distinctive && viable && defensible && composite >= 72) performanceKey = `grade_distinctive`;
            else if (distinctive && viable && defensible) performanceKey = `grade_credible`;
            else if (distinctive && !viable) performanceKey = `grade_lossmaking`;
            else if (distinctive) performanceKey = `grade_fragile`;
            else if (diff > this.START_DIFF + 12) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (distinctive && viable && defensible) insights.push(window.mySimulation.t(`insight_distinctive`));
            else if (distinctive && !viable) insights.push(window.mySimulation.t(`insight_lossmaking`));
            else if (distinctive) insights.push(window.mySimulation.t(`insight_fragile`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.spendingWar) insights.push(window.mySimulation.t(`insight_war`));
            if (ds.profLost) insights.push(window.mySimulation.t(`insight_profgone`));
            if (margin <= 0) insights.push(window.mySimulation.t(`insight_deficit`));
            if (distinctive && viable && defensible && fit >= 60) insights.push(window.mySimulation.t(`insight_owns`));

            return {
                diff: diff,
                fit: fit,
                resil: resil,
                margin: margin,
                distinctive: distinctive,
                viable: viable,
                defensible: defensible,
                sound: distinctive && viable && defensible,
                spendingWar: ds.spendingWar,
                profLost: ds.profLost,
                composite: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.spendingWar) return window.mySimulation.t(`hint_war`);
            if (ds.margin <= 0) return window.mySimulation.t(`hint_deficit`);
            if (ds.profLost) return window.mySimulation.t(`hint_prof`);
            if (state.currentPeriod >= 3 && ds.diff < 55) return window.mySimulation.t(`hint_behind`);
            if (ds.diff >= this.DISTINCTIVE_DIFF && ds.margin > 0 && ds.resil >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

